import csv, json, os, re, sys


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = ''.join(c.lower() if False else c.casefold() for c in s)
    s = ''.join(c if c.isalnum() else ' ' for c in s)
    return ' '.join(s.split())


def read_batches(cvr):
    batches = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        with open(p, encoding='utf-8', newline='') as f:
            text = f.read()
        lines = [l for l in text.split('\n')]
        meta = {}
        recs = []  # (contest, {rank: [marks]}) marks: ('c',id) or ('w',text)
        if name.endswith('.jsonl'):
            first = True
            for l in lines:
                if not l.strip():
                    continue
                o = json.loads(l)
                if first:
                    meta = o
                    first = False
                    continue
                rk = {}
                for m in o.get('marks', []):
                    r = int(m['rank'])
                    if 'write_in' in m and m['write_in'] is not None:
                        rk.setdefault(r, []).append(('w', m['write_in']))
                    else:
                        rk.setdefault(r, []).append(('c', m['candidate']))
                recs.append((o['contest'], rk))
        else:
            body = []
            for l in lines:
                if l.startswith('#'):
                    mm = re.match(r'#\s*([^:]+?)\s*:\s*(.*?)\s*$', l.rstrip('\r'))
                    if mm:
                        meta[mm.group(1).strip().lower()] = mm.group(2)
                elif l.strip():
                    body.append(l)
            rd = csv.reader(body)
            header = None
            for row in rd:
                if header is None:
                    header = [h.strip() for h in row]
                    continue
                if not row:
                    continue
                d = dict(zip(header, row))
                rk = {}
                for h, v in zip(header, row):
                    mm = re.fullmatch(r'rank(\d+)', h)
                    if not mm or not v.strip():
                        continue
                    r = int(mm.group(1))
                    for part in v.split('|'):
                        if part.strip() == '':
                            continue
                        if part.startswith('WI:'):
                            rk.setdefault(r, []).append(('w', part[3:]))
                        else:
                            rk.setdefault(r, []).append(('c', part))
                recs.append((d['contest'], rk))
        b = str(meta['batch'])
        rev = int(str(meta['revision']).strip())
        st = str(meta.get('status', 'final')).strip()
        if b not in batches or rev > batches[b][0]:
            batches[b] = (rev, st, recs)
    out = []
    for rev, st, recs in batches.values():
        if st != 'void':
            out.extend(recs)
    return out


def read_ballot(rk, maxr, cmap, withdrawn, wmap):
    """returns list of rankings: ('skip',), ('pass',), ('c',id), ('over',)"""
    seen = set()
    res = []
    for r in range(1, maxr + 1):
        marks = set()
        for kind, v in rk.get(r, []):
            if kind == 'w':
                w = wmap.get(norm_text(v))
                if w is not None:
                    marks.add(w)
            else:
                k = norm_id(v)
                if k in cmap:
                    marks.add(cmap[k])
                else:
                    marks.add(k)
        if not marks:
            res.append(('skip',))
            continue
        marks = {m for m in marks if m not in withdrawn}
        if not marks:
            res.append(('pass',))
            continue
        left = {m for m in marks if m not in seen}
        seen |= marks
        if not left:
            res.append(('skip',))
        elif len(left) == 1:
            res.append(('c', next(iter(left))))
        else:
            res.append(('over',))
    return res


def count_ballot(rankings, cont):
    n = len(rankings)
    for i, rk in enumerate(rankings):
        t = rk[0]
        if t == 'c':
            if rk[1] in cont:
                return rk[1]
        elif t == 'over':
            return None
        elif t == 'skip':
            if i + 1 >= n or rankings[i + 1][0] == 'skip':
                return None
    return None


def run_contest(c, recs):
    maxr = c['max_ranks']
    cmap = {}
    withdrawn = set()
    cands = []
    for cd in c['candidates']:
        k = norm_id(cd['id'])
        cmap[k] = k
        if cd.get('status') == 'withdrawn':
            withdrawn.add(k)
        else:
            cands.append(cd['id'])
    wmap = {}
    for w in c.get('write_ins', []):
        k = norm_id(w['id'])
        cmap[k] = k
        cands.append(w['id'])
        for t in [w['name']] + list(w.get('aliases', [])):
            wmap[norm_text(t)] = k
    names = {norm_id(i): i for i in cands}
    lot = {norm_id(x): i for i, x in enumerate(c.get('lot_order', []))}
    ballots = [read_ballot(rk, maxr, cmap, withdrawn, wmap) for rk in recs]
    cont = [norm_id(i) for i in cands]
    rounds = []
    hist = []
    winner = None
    total = len(ballots)
    while True:
        cs = set(cont)
        tal = {k: 0 for k in cont}
        active = 0
        for b in ballots:
            r = count_ballot(b, cs)
            if r is not None:
                tal[r] += 1
                active += 1
        hist.append(tal)
        rd = {"round": len(rounds) + 1,
              "tallies": {names[k]: v for k, v in tal.items()},
              "exhausted": total - active, "eliminated": []}
        rounds.append(rd)
        if active == 0:
            break
        w = [k for k, v in tal.items() if v * 2 > active]
        if w:
            winner = names[w[0]]
            break
        if len(cont) == 1:
            winner = names[cont[0]]
            break
        zeros = [k for k, v in tal.items() if v == 0]
        if zeros:
            el = zeros
        else:
            m = min(tal.values())
            tied = [k for k, v in tal.items() if v == m]
            for h in reversed(hist[:-1]):
                if len(tied) == 1:
                    break
                mm = min(h[k] for k in tied)
                tied = [k for k in tied if h[k] == mm]
            if len(tied) > 1:
                tied = [max(tied, key=lambda k: lot.get(k, -1))]
            el = tied
        rd["eliminated"] = sorted(names[k] for k in el)
        cont = [k for k in cont if k not in el]
        if not cont:
            break
    return {"contest": c['id'], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    recs = read_batches(os.path.join(inp, 'cvr'))
    by = {}
    for cid, rk in recs:
        by.setdefault(cid, []).append(rk)
    res = {"election": el['election'],
           "contests": [run_contest(c, by.get(c['id'], [])) for c in el['contests']]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
